add_expense:
def add_expense (s : State) (amount : Int) (category : String) (note : Option String := none) : Except String (Nat × State) :=
  if amount ≤ 0 then .error "amount must be positive"
  else if category = "" then .error "category must not be empty"
  else .ok (s.expenses.length + 1, { s with expenses := s.expenses ++ [{ cents := amount, category := category, note := note }] })
